class Solution:
    def maximumTop(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k == 0:
            return nums[0]
        if k == 1:
            return -1
        ans = max(nums[:k - 1])
        if k < n:
            ans = max(ans, nums[k - 1])
        elif k > n:
            ans = max(ans, max(nums))
        return ans

