class Solution {
    public int maximumTop(int[] nums, int k) {
        int n = nums.length;
        if (k == 0) return nums[0];
        if (k == 1) return -1;
        int ans = Integer.MIN_VALUE;
        for (int i = 0; i < Math.min(k - 1, n); i++) ans = Math.max(ans, nums[i]);
        if (k < n) ans = Math.max(ans, nums[k-1]);
        else if (k > n) { for (int v : nums) ans = Math.max(ans, v); }
        return ans;
    }
}

