var maximumTop = function(nums, k) {
    const n = nums.length;
    if (k === 0) return nums[0];
    if (k === 1) return -1;
    const pref = [];
    let m = -Infinity;
    for (const v of nums) { m = Math.max(m, v); pref.push(m); }
    let ans = pref[Math.min(k - 1, n) - 1];
    if (k < n) ans = Math.max(ans, nums[k - 1]);
    else if (k > n) ans = Math.max(ans, pref[n - 1]);
    return ans;
};
